WITH kept_keys AS (SELECT account_type, id FROM accounts INTERSECT SELECT account_type, id FROM accounts WHERE balance >= 26000), kept_rows AS (SELECT s.* FROM accounts s INNER JOIN kept_keys k ON s.account_type = k.account_type AND s.id = k.id) SELECT s.id, s.customer_id, s.account_type, s.opened_date, (SELECT SUM(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS sum_account_balance FROM kept_rows s ORDER BY id DESC NULLS FIRST;
